// ============================================================
//  CONFIGURATION — à adapter avant d'activer le workflow
// ============================================================
const CONFIG = {
  brand: 'Portefolia',
  tagline: 'Expose ton futur.',
  domain: 'portefolia.tech',
  frontUrl: 'https://portefolia.tech',
  apiUrl: 'https://portefolia.tech/api',          // ou http://localhost:<port>/api si n8n tourne sur le même VPS
  fromEmail: 'Portefolia <support@portefolia.tech>', // doit être l'adresse du compte SMTP
  replyTo: 'support@portefolia.tech',
  adminEmail: 'contact@portefolia.tech',        // boîte qui reçoit les alertes admin
  supportWhatsapp: '+221 78 131 13 71',
  colors: { primary: '#1B5E20', accent: '#2E7D32' }, // vert Portefolia
  telegram: { enabled: false, chatId: '' },          // alertes admin sur Telegram (optionnel)
  whatsapp: {                                        // WhatsApp Cloud API (optionnel, templates approuvés par Meta)
    enabled: false,
    phoneNumberId: '',
    templates: { created: 'precommande_recue', paid: 'precommande_confirmee' },
  },
};
return $input.all().map((i) => ({ json: { ...i.json, config: CONFIG } }));

// ---------- Helpers (échappement, format, gabarit e-mail) ----------
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fcfa = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' F CFA';
const firstName = (p) => (p.first_name || String(p.full_name || '').trim().split(/\s+/)[0] || '').trim();
const para = (html) => `<p style="font-size:15px;line-height:1.6;margin:0 0 12px">${html}</p>`;
const row = (k, v) => `<tr><td style="padding:7px 0;color:#6b7280;width:45%;vertical-align:top">${esc(k)}</td><td style="padding:7px 0;font-weight:600">${v}</td></tr>`;
const table = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb;margin:16px 0">${rows.join('')}</table>`;
const hoursSince = (iso) => (iso ? Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 36e5)) : null);

function layout(cfg, { preheader = '', title, body, cta }) {
  const button = cta && cta.url
    ? `<p style="margin:28px 0 8px;text-align:center"><a href="${esc(cta.url)}" style="background:${cfg.colors.accent};color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:8px;font-weight:600;display:inline-block">${esc(cta.label)}</a></p>`
    : '';
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<span style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">
<tr><td style="background:${cfg.colors.primary};padding:22px 28px;color:#ffffff;font-size:20px;font-weight:700">${esc(cfg.brand)}<div style="font-size:12px;font-weight:400;opacity:.85;margin-top:4px">${esc(cfg.tagline)}</div></td></tr>
<tr><td style="padding:28px">
<h1 style="font-size:20px;line-height:1.3;margin:0 0 16px">${esc(title)}</h1>
${body}
${button}
</td></tr>
<tr><td style="padding:18px 28px;background:#f9fafb;font-size:12px;line-height:1.5;color:#6b7280">Vous recevez cet e-mail suite à votre précommande sur ${esc(cfg.domain)}. Une question ? Répondez à cet e-mail ou écrivez-nous sur WhatsApp au ${esc(cfg.supportWhatsapp)}.</td></tr>
</table></td></tr></table></body></html>`;
}

function waveBlock(p, pay) {
  return `<div style="background:#eef6ff;border-radius:10px;padding:16px 18px;margin:16px 0;font-size:14px;line-height:1.7">
<strong>Comment payer avec Wave</strong><br>
1. Envoyez <strong>${esc(fcfa(p.total_amount))}</strong> au <strong>${esc(pay.wave_number)}</strong>${pay.wave_link ? ` ou passez par <a href="${esc(pay.wave_link)}">ce lien de paiement Wave</a>` : ''}.<br>
2. Mettez la référence <strong>${esc(p.reference)}</strong> en note du transfert.<br>
3. Cliquez sur le bouton ci-dessous et saisissez l'identifiant de la transaction Wave (visible dans l'historique de l'application).
</div>`;
}

function recap(p, extra = []) {
  return table([
    row('Référence', esc(p.reference)),
    row('Nom imprimé sur la carte', esc(p.card_name)),
    row('Quantité', esc(p.quantity)),
    row('Montant total', esc(fcfa(p.total_amount))),
    ...extra,
  ]);
}

// ---------- Construction des messages selon l'événement ----------
const out = [];

for (const item of $input.all()) {
  const cfg = item.json.config;
  const b = item.json.body || {};
  const p = b.preorder || {};
  const pay = b.payment || {};
  const stats = b.stats || {};
  const links = b.links || {};
  if (!b.event || !p.id || !p.email) continue; // payload invalide : on ignore

  const prenom = esc(firstName(p));
  let client = null;
  let admin = null;
  let whatsapp = null;

  const adminRows = [
    row('Référence', esc(p.reference)),
    row('Client', esc(p.full_name)),
    row('E-mail', esc(p.email)),
    row('Téléphone', esc(p.phone)),
    row('Nom sur la carte', esc(p.card_name)),
    row('Quantité', esc(p.quantity)),
    row('Montant', esc(fcfa(p.total_amount))),
  ];
  const lot = stats.batch_threshold ? `${stats.paid_count || 0}/${stats.batch_threshold}` : String(stats.paid_count || 0);

  switch (b.event) {
    case 'preorder.created': {
      const subject = `Précommande ${p.reference} reçue – finalisez votre paiement Wave`;
      client = { subject, html: layout(cfg, {
        preheader: `Payez ${fcfa(p.total_amount)} avec Wave pour réserver votre carte NFC.`,
        title: `Merci ${prenom}, votre précommande est enregistrée`,
        body: para('Votre carte NFC Portefolia est presque réservée. Il ne reste qu\'une étape : le paiement Wave.')
          + recap(p) + waveBlock(p, pay)
          + para('<span style="color:#6b7280;font-size:13px">Sans paiement sous 72 h, la précommande est annulée automatiquement. Vous pourrez en refaire une à tout moment.</span>'),
        cta: { label: 'Déclarer mon paiement Wave', url: links.tracking_url },
      }) };
      admin = {
        subject: `🆕 Précommande ${p.reference} — ${fcfa(p.total_amount)}`,
        html: layout(cfg, { title: 'Nouvelle précommande NFC', body: table([...adminRows, row('Précommandes payées', esc(lot))]) + para('Statut : en attente du paiement Wave.'), cta: { label: 'Ouvrir dans l\'admin', url: links.admin_url } }),
        text: `🆕 <b>Nouvelle précommande ${esc(p.reference)}</b>\n${esc(p.full_name)} — ${esc(p.phone)}\n${esc(p.quantity)} carte(s) — ${esc(fcfa(p.total_amount))}\nPayées : ${esc(lot)}`,
      };
      if (cfg.whatsapp.enabled && cfg.whatsapp.templates.created) {
        whatsapp = { template: cfg.whatsapp.templates.created, params: [firstName(p), p.reference, fcfa(p.total_amount)] };
      }
      break;
    }

    case 'preorder.payment_submitted': {
      client = { subject: `Paiement Wave reçu pour ${p.reference} – vérification en cours`, html: layout(cfg, {
        preheader: 'Nous vérifions votre transaction Wave.',
        title: `Merci ${prenom}, nous vérifions votre paiement`,
        body: para('Nous avons bien reçu votre déclaration de paiement. Nous la vérifions et vous confirmons sous 24 h ouvrées.')
          + recap(p, [row('Transaction Wave', esc(p.wave_transaction_id))]),
        cta: { label: 'Suivre ma précommande', url: links.tracking_url },
      }) };
      admin = {
        subject: `⏳ Paiement Wave à valider — ${p.reference}`,
        html: layout(cfg, { title: 'Paiement Wave à vérifier', body:
          para('Vérifiez la transaction dans Wave Business, puis validez ou refusez dans l\'admin.')
          + table([...adminRows, row('ID transaction Wave', esc(p.wave_transaction_id)), row('Numéro Wave payeur', esc(p.wave_sender_phone || '—'))]),
          cta: { label: 'Valider le paiement', url: links.admin_url } }),
        text: `⏳ <b>Paiement à valider ${esc(p.reference)}</b>\n${esc(p.full_name)} — ${esc(fcfa(p.total_amount))}\nTransaction : <code>${esc(p.wave_transaction_id)}</code>`,
      };
      break;
    }

    case 'preorder.paid': {
      client = { subject: '✅ Paiement confirmé – votre carte NFC Portefolia est réservée', html: layout(cfg, {
        preheader: `Précommande ${p.reference} confirmée.`,
        title: `C'est confirmé, ${prenom} !`,
        body: para('Nous avons validé votre paiement Wave. Votre carte NFC Portefolia est réservée.')
          + recap(p)
          + para('<strong>La suite :</strong> nous lançons la fabrication par lots et vous informons à chaque étape, jusqu\'à la livraison.')
          + para('En attendant, préparez votre portfolio : c\'est lui qui s\'affichera quand quelqu\'un approchera son téléphone de votre carte.'),
        cta: { label: 'Préparer mon portfolio', url: links.portfolio_url || cfg.frontUrl },
      }) };
      if (whatsappEnabled(cfg, 'paid')) {
        whatsapp = { template: cfg.whatsapp.templates.paid, params: [firstName(p), p.reference] };
      }
      // Alerte admin à chaque lot complet (10, 20, 30… précommandes payées)
      if (stats.batch_threshold && Number(stats.paid_count) > 0 && Number(stats.paid_count) % Number(stats.batch_threshold) === 0) {
        admin = {
          subject: `🎯 ${stats.paid_count} précommandes payées — seuil du lot atteint`,
          html: layout(cfg, { title: 'Un lot est complet', body: para(`Vous avez atteint <strong>${esc(stats.paid_count)}</strong> précommandes payées. Vous pouvez lancer la commande groupée chez le fabricant.`), cta: { label: 'Voir les précommandes', url: links.admin_list_url || links.admin_url } }),
          text: `🎯 <b>Seuil atteint : ${esc(stats.paid_count)} précommandes payées.</b> Lancer la commande groupée.`,
        };
      }
      break;
    }

    case 'preorder.rejected': {
      client = { subject: `Paiement non confirmé pour la précommande ${p.reference}`, html: layout(cfg, {
        preheader: 'Nous n\'avons pas pu confirmer votre paiement Wave.',
        title: `${prenom}, nous n'avons pas pu confirmer votre paiement`,
        body: para(`Motif : <strong>${esc(p.rejection_reason || 'transaction introuvable ou montant différent')}</strong>.`)
          + para('Votre précommande reste ouverte. Vérifiez la transaction puis déclarez-la à nouveau, ou répondez à cet e-mail si vous pensez qu\'il s\'agit d\'une erreur.')
          + waveBlock(p, pay),
        cta: { label: 'Déclarer à nouveau mon paiement', url: links.tracking_url },
      }) };
      break;
    }

    case 'preorder.expired':
    case 'preorder.cancelled': {
      const expired = b.event === 'preorder.expired';
      client = { subject: `Précommande ${p.reference} annulée${expired ? ' (paiement non reçu)' : ''}`, html: layout(cfg, {
        title: `${prenom}, votre précommande a été annulée`,
        body: para(expired
          ? 'Nous n\'avons pas reçu de paiement Wave dans les 72 h, la précommande a donc été annulée.'
          : `Votre précommande ${esc(p.reference)} a été annulée${p.rejection_reason ? ` (motif : ${esc(p.rejection_reason)})` : ''}.`)
          + para('Vous pouvez refaire une précommande à tout moment.'),
        cta: { label: 'Refaire une précommande', url: links.preorder_url || cfg.frontUrl + '/nfc-types' },
      }) };
      break;
    }

    default:
      continue; // événement inconnu : rien à envoyer
  }

  // Renvoi du lien de suivi demandé par le client : pas d'alerte admin
  if (b.audience === 'client') admin = null;

  out.push({ json: {
    event_id: b.event_id || null,
    event: b.event,
    preorder_id: p.id,
    reference: p.reference,
    apiUrl: cfg.apiUrl,
    from: cfg.fromEmail,
    replyTo: cfg.replyTo,
    client: client ? { to: p.email, ...client } : null,
    admin: admin ? { to: cfg.adminEmail, ...admin } : null,
    telegram: admin && cfg.telegram.enabled ? { chatId: cfg.telegram.chatId } : null,
    whatsapp: whatsapp ? { to: String(p.phone || '').replace(/\D/g, ''), phoneNumberId: cfg.whatsapp.phoneNumberId, ...whatsapp } : null,
  } });
}

function whatsappEnabled(cfg, key) { return cfg.whatsapp.enabled && !!cfg.whatsapp.templates[key]; }

return out;
